-- One PENDING proposal so the Approvals tab + the 🙋 badge aren't empty on minute one.
insert into agent_actions (agent_key, idempotency_key, payload, status, expires_at)
select 'overdue-chaser', 'seed-demo-proposal-001',
       '{"kind":"draft","ref":"ERM-27001-2026-001","owner":"Information Security","severity":"High","channel":"email","text":"Hi Information Security team, risk ERM-27001-2026-001 (Unauthorised access to customer data) has a treatment action that was due on 2026-08-23 and is still open. Could you share the current status and a revised date? Thanks — CGI","note":"High risk action overdue — draft a reminder to Information Security?"}'::jsonb,
       'proposed', now() + interval '7 days'
where not exists (select 1 from agent_actions where idempotency_key = 'seed-demo-proposal-001');
